const crypto = require('crypto');
const input = $input.first().json;
const headers = Object.fromEntries(Object.entries(input.headers || {}).map(([key,value]) => [key.toLowerCase(), String(value)]));
const body = input.body || {};
const eventId = headers['x-career-event-id'];
const timestamp = headers['x-career-timestamp'];
const provided = String(headers['x-career-signature'] || '').replace(/^sha256=/, '');
const secret = process.env.CAREER_N8N_WEBHOOK_SECRET;
if (!secret || !eventId || !timestamp || !provided) throw new Error('CAREER_AUTH_MISSING');
if (eventId !== body.eventId || timestamp !== body.timestamp) throw new Error('CAREER_EVENT_MISMATCH');
const eventTime = Date.parse(timestamp);
if (!Number.isFinite(eventTime) || Math.abs(Date.now() - eventTime) > 300000) throw new Error('CAREER_TIMESTAMP_EXPIRED');
const allowed = ['JOB_HIGH_MATCH','JOB_MATCH_DIGEST_READY','INTEGRATION_TEST'];
if (!allowed.includes(body.type)) throw new Error('CAREER_EVENT_NOT_ALLOWED');
const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${JSON.stringify(body)}`).digest('hex');
const a = Buffer.from(expected, 'hex'); const b = Buffer.from(provided, 'hex');
if (a.length !== b.length || !crypto.timingSafeEqual(a,b)) throw new Error('CAREER_SIGNATURE_INVALID');
const state = $getWorkflowStaticData('global'); state.seen ||= {};
for (const [id,seenAt] of Object.entries(state.seen)) if (Date.now() - seenAt > 600000) delete state.seen[id];
if (state.seen[eventId]) throw new Error('CAREER_REPLAY_BLOCKED'); state.seen[eventId] = Date.now();
return [{json: body}];

const event = $input.first().json; const d = event.data || {};
const clean = value => String(value || '').replace(/[
]+/g, ' ').slice(0, 500);
let message;
if (event.type === 'JOB_HIGH_MATCH') message = `🎯 *Vaga com alto match*
${clean(d.title)} — ${clean(d.company)}
Match: ${Number(d.fitScore || 0)}% | ${clean(d.eligibility)}
${clean(d.location)}
${clean(d.applicationUrl)}${d.tailoringRunId ? `
Tailoring preparado: REVIEW_REQUIRED (${clean(d.tailoringRunId)})` : d.resumeVersionId ? `
Currículo preparado: REVIEW_REQUIRED (${clean(d.resumeVersionId)})` : ''}`;
else if (event.type === 'JOB_MATCH_DIGEST_READY') message = `📌 *Resumo Career Unified*
${Number(d.matchCount || 0)} novas vagas elegíveis. Melhor match: ${Number(d.topScore || 0)}%.
Abra o Hub para revisar; nenhuma candidatura foi enviada.`;
else message = `✅ *Teste Career Unified*
${clean(d.message || 'Integração ativa.')}
Nenhuma candidatura foi enviada.`;
return [{json:{eventId:event.eventId,message}}];
